    "logo.chico": "Police checkpoint", "carga.lugar": "National Route 11 · Presidencia Roca, Chaco, Argentina", "carga.consejo": "Tip:", "carga.error": "Could not load: ", "carga.modelos": "Loading 3D models (Rezona)…", "carga.armando": "Building the road and the checkpoint…",
    consejos: ["Compare the vehicle's plate with the one on the green registration card: if they don't match, look it up on the tablet.", "Someone who trembles, avoids your eyes and changes the story may be hiding something. Or may just be nervous.", "Over 0.5 g/l on the breathalyzer is a serious offense: the vehicle is impounded and the driver detained.", "If the name on the ID isn't the one the tablet shows for that number, the ID is fake: arrest.", "With the flashlight [F] in the trunk, move things around: what's hidden goes at the bottom.", "Arresting an innocent person costs 100 reputation. Drop below zero and you're relieved of duty.", "Look at the headlights from the front: driving with a burnt-out light is a minor offense.", "Dispatch radio sometimes tells you who to look for. Check the News on the tablet."],
    "turno.dia": "Day", "turno.tarde": "Evening", "turno.noche": "Night", "turno.dia.d": "Light traffic and good light to read the papers.", "turno.tarde.d": "Sunset over the forest. Night falls halfway through the shift.", "turno.noche.d": "Little light, more alcohol and the flashlight in hand.",
    rangos: ["Probationary officer", "Officer", "Corporal", "Sergeant", "Senior officer", "Highway Patrol Commissioner"],
    "si": "On", "no": "Off", "cerrar": "Close", "volver": "Back", "min": "min",
