    "ayuda.controles": "Controls", "ayuda.teclas": [["W A S D", "walk (Shift runs)"], ["Mouse", "look (click to capture it)"], ["E", "talk to the driver through the window / leave a detainee in the zone"], ["F", "search the trunk with the flashlight (away from the car: turn on the flashlight)"], ["R", "handcuff"], ["Q", "call the patrol car for transfer"], ["Esc / P", "pause or close the open window"]],
    "ayuda.tactil": "On the phone: stick on the left to walk, drag on the screen to look and use the buttons on the right. If you hold it upright, the game rotates by itself.",
    "ayuda.revisar": "What to check", "ayuda.docs": "Documents: ", "ayuda.docsT": "ID, driver's license, green registration card and insurance. Check expiry dates, that the card's plate is the vehicle's and that the ID photo is the driver.", "ayuda.tablet": "Tablet: ", "ayuda.tabletT": "look up the ID (do the system's name and photo match?) and the plate (theft report?).", "ayuda.alco": "Breathalyzer: ", "ayuda.alcoT": "from 0.0 to 2.5 g/l. Over 0.5 is positive. Red eyes and slurred speech are signs.", "ayuda.sosp": "Suspects (30%): ", "ayuda.sospT": "they tremble, avoid eye contact, change their story. Some carry drugs or weapons hidden at the bottom of the trunk.", "ayuda.arresto": "Arrest: ", "ayuda.arrestoT": "handcuff them [R], take them to the Detainee Zone (yellow rectangle) and call the patrol car [Q].",
    "ayuda.resoluciones": "Decisions", "ayuda.colRes": "Decision", "ayuda.colCuando": "When", "ayuda.colPts": "Points",
    "ayuda.pasarT": "Everything in order.", "ayuda.multarT": "Minor offenses: no seatbelt (or helmet), burnt-out lights, no valid insurance, license expired less than a year ago.", "ayuda.retenerT": "Serious offenses: alcohol > 0.5 g/l, license expired over a year ago, no registration card, no license for that vehicle. The driver is detained.", "ayuda.arrestarT": "Crimes: arrest warrant, drugs or weapons in the trunk, fake ID, stolen vehicle.",
