    "ayuda.controles": "Controles", "ayuda.teclas": [["W A S D", "andar (Shift corre)"], ["Mouse", "olhar (clique para capturar)"], ["E", "falar com o motorista pela janela / deixar o detido na zona"], ["F", "revistar o porta-malas com a lanterna (longe do carro: acender a lanterna)"], ["R", "algemar"], ["Q", "chamar a viatura para o transporte"], ["Esc / P", "pausa ou fechar a janela aberta"]],
